        {"name": "modality", "value": "mandatory"},
        {"name": "scope", "value": "period"},
        {"name": "produces", "value": "benefits_taxable_regular"},
        {
          "name": "condition",
          "value": "tax_year > 2022 or (employer('financial_year_2022_start_year') != None and employer('financial_year_2022_start_month') != None)"
        },
        {
          "name": "expression",
          "value": "round(max(0, benefit('regular_natura_and_enjoyment') - benefit('regular_exempt_natura_and_enjoyment')), 1, 'half_up') if (tax_year > 2022 or employer('financial_year_2022_start_year') < 2022 or (employer('financial_year_2022_start_year') == 2022 and month >= employer('financial_year_2022_start_month'))) else 0"
        }
      ],
      "source": [
        {
          "document": "PMK-66-2023",
          "provision": "Pasal 3 ayat (1)",
          "page": 5,
          "quote": "Penggantian atau imbalan sehubungan dengan pekerjaan\natau jasa yang diterima atau diperoleh dalam bentuk\nnatura dan/atau kenikmatan merupakan penghasilan\nyang menjadi objek Pajak Penghasilan sebagaimana\ndimaksud dalam Pasal 4 ayat (1) huruf a Undang-Undang\nPajak Penghasilan."
        },
        {
          "document": "PMK-66-2023",
          "provision": "Pasal 3 ayat (6) huruf a dan huruf b",
          "page": 5,
          "quote": "Ketentuan mengenai penggantian atau imbalan\nsehubungan dengan pekerjaan atau jasa yang diterima\natau diperoleh dalam bentuk natura dan/atau\nkenikmatan sebagaimana dimaksud pada ayat (1) sebagai\nobjek Pajak Penghasilan berlaku s~jak:\na. tanggal 1 Januart 2022, bagi Pegawai atau penerima\npenggantian atau imbalan yang menerima atau\nmemperoleh penggantian atau imbalan dalam bentuk\nnatura dan/atau kenikmatan dart pemberi kerja atau\npemberi penggantian atau imbalan sebagaimana\ndimaksud dalam Pasal 2 ayat (7) huruf a ; atau\nb. tahun buku 2022 dart pemberi kerja atau pemberi\npenggantian atau imbalan dimulai"
        },
        {
          "document": "PMK-66-2023",
          "provision": "Pasal 4",
          "page": 6,
          "quote": "Dikecualikan dart objek Pajak Penghasilan atas penggantian\natau imbalan dalam bentuk natura dan/atau kenikmatan\nsebagaimana dimaksud dalam Pasal 3 ayat (1) meliputi:\na. makanan, bahan makanan, bahan minuman, dan/atau\nminuman bagi seluruh Pegawai;\nb. natura dan/atau kenikmatan yang disediakan di daerah\ntertentu;\nc. natura dan/atau kenikmatan yang harus disediakan oleh\npemberi kerja dalam pelaksanaan pekerjaan;\nd. natura dan/atau kenikmatan yang bersumber atau\ndibiayai anggaran pendapatan dan belanja negara,\nanggaran pendapatan dan belanja daerah, dan/atau\nanggaran pendapatan dan belanja desa; atau\ne. natura dan/atau kenikmatan dengan jenis dan/atau\nbatasan tertentu."
        },
        {
          "document": "PMK-66-2023",
          "provision": "Pasal 7 ayat (3)",
          "page": 8,
          "quote": "tennasuk diperuntukkan bagi natura dan/atau\nkenikmatan yang diterima atau diperoleh penerima selama\ntahun 2022."
        },
        {
          "document": "PMK-66-2023",
          "provision": "Penutup — penetapan",
          "page": 20,
          "quote": "Ditetapkan di Jakarta\npada tanggal 27 Juni 2023"
        }
      ]
    },
