    {
      "kind": "parameter",
      "id": "PAR.FOOD_COUPON_EXEMPTION_MONTHLY.2023",
      "label": "Monthly statutory food coupon exemption floor",
      "label_id": "Batas dasar pengecualian kupon makanan sebulan",
      "valid_from": "2023-07-01",
