      "id": "FACT.FOOD_COUPON_TAXABLE",
      "label": "Taxable food coupons and equivalent meal reimbursements",
      "label_id": "Kupon makanan dan penggantian setara yang kena pajak",
      "valid_from": "2023-07-01",
      "valid_until": null,
      "recorded_on": "2023-06-27",
      "fields": [
        {"name": "name", "value": "food_coupon_taxable"},
