    {
      "kind": "rule",
      "id": "REG.NATURA.MEAL_COUPONS_TAXABLE",
      "label": "Tax meal-coupon excess over the higher applicable monthly ceiling",
      "label_id": "Pengenaan pajak atas kelebihan kupon makanan dari batas bulanan yang lebih tinggi",
      "valid_from": "2023-07-01",
      "valid_until": null,
      "recorded_on": "2023-06-27",
      "fields": [
        {"name": "layer", "value": "regulation"},
        {"name": "modality", "value": "mandatory"},
        {"name": "scope", "value": "period"},
        {"name": "produces", "value": "meal_coupons_taxable"},
        {"name": "expression", "value": "round(max(0, benefit('qualifying_meal_coupons') - max(param('meal_coupon_exemption_floor'), hr('workplace_meal_cost_per_employee'))), 1, 'down')"}
