      "id": "REG.NATURA.WITHHOLDING_IRREGULAR",
      "label": "Irregular benefits included in employer withholding after valuation and exemptions",
      "label_id": "Natura tidak teratur dalam dasar pemotongan setelah penilaian dan pengecualian",
      "valid_from": "2023-07-01",
      "valid_until": null,
