      "fields": [
        {"name": "layer", "value": "regulation"},
        {"name": "modality", "value": "mandatory"},
        {"name": "scope", "value": "period"},
        {"name": "produces", "value": "benefits_taxable_irregular"},
        {"name": "expression", "value": "round(max(0, benefit('irregular_natura_market_value') + benefit('irregular_resale_nonproperty_cogs') + benefit('irregular_amenity_monthly_allocated_cost') - (benefit('irregular_workplace_meals') if hr('workplace_meals_for_all_employees') else 0) - benefit('irregular_statutorily_required_safety_benefits') - benefit('irregular_public_budget_benefits') - (benefit('irregular_qualifying_remote_facilities') if hr('remote_area_designation_valid') else 0) - benefit('irregular_annex_exempt_value')), 1, 'down') + meal_coupons_taxable - round(meal_coupons_taxable * hr('taxable_meal_coupon_regular_share'), 1, 'down')"},
        {"name": "overrides", "value": "REG.NATURA.TAXABLE_IRREGULAR"}
