      "id": "REG.TER.RUNNING",
      "label": "Monthly effective withholding outside the final tax period",
      "label_id": "Pemotongan dengan tarif efektif bulanan selain masa pajak terakhir",
      "valid_from": "2024-01-01",
      "valid_until": null,
      "recorded_on": "2023-12-27",
      "fields": [
